# Run Tests -- the one entry point for this project's tests. Generated by CruftFree, do not edit manually.
#
# Usage:
#   ./tests/run-tests.ps1                    # Run the unit tests
#   ./tests/run-tests.ps1 -Unit              # The same: this project has no deploy tests
#   ./tests/run-tests.ps1 -Unit --verbose    # Forward an argument to the runner
#
# Every argument besides the switches is forwarded verbatim to the runner this
# script starts. Every runner accepts --verbose; the unit runner also accepts
# --parallel (run the services' tests concurrently) and the deploy runner
# --results-dir <directory> (where its results and container logs go).
#
# This deployment starts no container orchestration on the developer's
# machine, so it carries no compose-driven deploy harness and this script
# offers no switch that would start one.

param(
    [switch]$Unit
)

$ErrorActionPreference = "Stop"

# Every runner path below is relative to the project root: anchor there for the
# run and give the caller its own location back afterwards, however it ends.
Push-Location -LiteralPath (Join-Path $PSScriptRoot '..')
try {
    Write-Host "Running unit tests..." -ForegroundColor Cyan
    python tests/unit_tests.py @args
    if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
}
finally {
    Pop-Location
}
